function renderSettings(){$('#main').innerHTML=heading('Settings','Configure your workspace and review connection requirements.')+`<div class="settings-grid ss-isp-wrap"><section class="card settings-card ss-isp"><h2>ISP details</h2><p class="muted">Shown on receipts, invoices and the dashboard.</p><div class="ss-isp-fields"><label>Business name<input id="workspace-name" value="${h(state.session.workspace.name)}" maxlength="100"></label><label>Description<textarea id="ws-description" rows="2" maxlength="300">${h(state.session.workspace.description||'')}</textarea></label><label>Address<input id="ws-address" value="${h(state.session.workspace.address||'')}" maxlength="160"></label><label>Email<input id="ws-email" type="email" value="${h(state.session.workspace.email||'')}" maxlength="120"></label><label>Phone<input id="ws-phone" value="${h(state.session.workspace.phone||'')}" maxlength="20" placeholder="0712 345 678"></label><label>Country<input id="ws-country" value="${h(state.session.workspace.country||'Kenya')}" maxlength="60"></label><label>Currency<select id="ws-currency">${['KES','UGX','TZS','RWF','USD'].map(c=>`<option ${(state.session.workspace.currency||'KES')===c?'selected':''}>${c}</option>`).join('')}</select></label></div>${state.session.user.role==='admin'?'<button class="button primary" id="save-workspace">Save ISP details</button>':''}<p>Database: server-side SQLite. Device credentials: encrypted on disk. Back up the database and master key together.</p></section></div><div class="provider-grid ss-pairs"><section class="card"><h3>Appearance</h3><p>Switch between light and dark themes.</p><button class="button secondary" data-theme>Toggle theme</button></section><section class="card" id="set-providers"><h3>SMS & payments</h3><p class="muted">Checking your providers…</p></section><section class="card"><h3>MikroTik RouterOS</h3><p>Uses RouterOS REST over verified HTTPS. Set a router origin, save a read-only RouterOS user, then check the device. Private routes or VPN connectivity must already reach the router.</p><a class="button secondary" href="#mikrotiks">Manage routers</a> <button class="button primary" data-new-router-agent>Connect with script</button><p>RouterOS 7.16+ can report over HTTPS every 30 seconds through a generated connection script. Direct REST monitoring needs LAN or VPN reachability.</p></section><section class="card"><h3>OLT connection</h3><p>Read OLT identity with direct SNMP v2c/v3. ONU state and power require a matching vendor MIB mapping. Provisioning uses a separately implemented vendor gateway with confirmation. No OLT model has been physically verified yet.</p><a class="button secondary" href="#olts">Manage OLTs</a></section><section class="card"><h3>TR-069 / GenieACS</h3><p>Connect your own ACS to list CPEs, inspect check-in status, refresh parameters, change observed Wi-Fi networks and request reboots. Queued and uncertain outcomes remain visible.</p><a class="button secondary" href="#tr069">Manage TR-069</a></section><section class="card"><h3>WireGuard</h3><p>Each router gets its own WireGuard tunnel to netops when you link it (Link a MikroTik). Staff Winbox access and the server's WireGuard details are under WireGuard &amp; Winbox access.</p><a class="button secondary" href="#wireguard">WireGuard &amp; Winbox access</a></section></div>`;paintProviders();}
function renderAssistant(){$('#main').innerHTML=heading('Network assistant','Review network findings and next actions.')+notice('AI provider setup required','No AI service is connected. The findings below use saved observations from your equipment.',true)+`<section class="card settings-card"><h2>Current network findings</h2>${rows('devices').filter(d=>d.status!=='online').map(d=>`<p><button class="link-button" data-device="${d.id}">${h(d.name)}</button> — ${h(d.status)}. ${h(d.lastError||'Configure a connection and collect a device check.')}</p>`).join('')||'<p>No device issues have been observed.</p>'}<p>These findings are direct checks of saved device state, without an AI model.</p></section>`;}
function renderMap(){const items=['zones','odbs','closures','devices'].flatMap(kind=>rows(kind).map(r=>({...r,kind}))),coordinates=items.filter(r=>Number.isFinite(r.latitude)&&Number.isFinite(r.longitude));const lats=coordinates.map(r=>r.latitude),lons=coordinates.map(r=>r.longitude);const minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons);const positions=new Map(items.map((r,i)=>[r.id,Number.isFinite(r.latitude)&&Number.isFinite(r.longitude)?{x:80+(r.longitude-minLon)/Math.max(maxLon-minLon,.001)*800,y:460-(r.latitude-minLat)/Math.max(maxLat-minLat,.001)*360}:{x:100+(i%6)*155,y:75+Math.floor(i/6)*100}]));const edges=[...rows('cables').map(c=>[c.fromId,c.toId,c.name]),...rows('devices').filter(d=>d.parentId).map(d=>[d.parentId,d.id,d.pon||'PON'])];$('#main').innerHTML=heading('Network map','Explore recorded physical links and OLT → ONU relationships.','<a class="button secondary" href="/api/map/export?format=geojson">Download GeoJSON</a><a class="button secondary" href="/api/map/export?format=kml">Download KML</a>')+`<section class="card"><div class="map-toolbar"><button class="button secondary" data-map-zoom="1.2">Zoom in</button><button class="button secondary" data-map-zoom="0.8">Zoom out</button><button class="button secondary" data-map-reset>Reset view</button><span>Drag to pan · select a node for details · ${coordinates.length}/${items.length} nodes have geographic coordinates</span></div>${items.length?`<svg id="network-canvas" class="network-canvas" viewBox="0 0 1000 540" role="group" aria-label="Network topology"><g id="map-layer">${edges.map(([a,b,label])=>{const p=positions.get(a),q=positions.get(b);return p&&q?`<line x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}"><title>${h(label)}</title></line>`:'';}).join('')}${items.map(r=>{const p=positions.get(r.id);return `<g tabindex="0" role="button" aria-label="${h(r.name)}" data-map-kind="${r.kind}" data-map-id="${r.id}" class="${r.status==='offline'?'offline':''}" transform="translate(${p.x},${p.y})"><circle r="17"/><text text-anchor="middle" y="36">${h(r.name.slice(0,25))}</text><text text-anchor="middle" y="52" style="font-size:9px">${h(r.type||r.kind)}</text></g>`;}).join('')}</g></svg>`:'<div class="list-empty"><h3>Your network map starts here</h3><p>Add devices, zones, ODBs and cables to plot connections.</p></div>'}</section>`+notice('Layout','Nodes with coordinates are projected by latitude and longitude. Other nodes use a schematic layout. GIS exports include only recorded coordinates, with cables drawn between endpoints. Customer contact details are excluded.');const svg=$('#network-canvas');if(!svg)return;let drag=null,offset={x:0,y:0},scale=1;const apply=()=>$('#map-layer').setAttribute('transform',`translate(${offset.x},${offset.y}) scale(${scale})`);svg.onpointermove=e=>{if(!drag)return;const factor=1000/svg.getBoundingClientRect().width;offset={x:(e.clientX-drag.x)*factor+drag.ox,y:(e.clientY-drag.y)*factor+drag.oy};apply();};svg.onpointerdown=e=>{if(e.target.closest('[data-map-id]'))return;drag={x:e.clientX,y:e.clientY,ox:offset.x,oy:offset.y};svg.setPointerCapture(e.pointerId);};svg.onpointerup=()=>drag=null;$$('[data-map-zoom]').forEach(b=>b.onclick=()=>{scale=Math.min(4,Math.max(.25,scale*Number(b.dataset.mapZoom)));apply();});$('[data-map-reset]').onclick=()=>{offset={x:0,y:0};scale=1;apply();};}
function renderDiscovery(){$('#main').innerHTML=heading('Unconfigured ONUs','Discover subscriber units on connected OLTs and authorize them with a service profile.')+tabs([['olt-onus','All ONUs'],['unconfigured','Unconfigured'],['olt-configuration','Service profiles']])+notice('Live discovery','Select an OLT, refresh its observations, then choose an observed serial. Authorization is successful only when the gateway confirms it.')+`<section class="card settings-card"><label>OLT<select id="discovery-olt"><option value="">Select a connected OLT…</option>${rows('devices').filter(d=>d.type==='olt'&&d.driver==='olt-gateway').map(d=>`<option value="${d.id}">${h(d.name)}</option>`).join('')}</select></label><button class="button secondary" id="refresh-discovery">Refresh discovery</button><div id="discovery-results"></div></section>`;$('#refresh-discovery').onclick=async event=>{const olt=$('#discovery-olt').value;if(!olt)return toast('Select an OLT with a configured gateway');const button=event.currentTarget;button.disabled=true;try{const check=await api('records/devices/'+olt+'/poll','POST',{});if(!check.online)throw new Error(check.error);const result=await api('records/devices/'+olt+'/discover');$('#discovery-results').innerHTML=table(['SERIAL','PON','ACTION'],result.onus,onu=>`<tr><td>${h(onu.serial)}</td><td>${h(onu.pon)}</td><td>${(NetworkPermissions.equipment(state.session.user.role)||state.session.user.role==='installer')?`<button class="button primary" data-authorize-olt="${olt}" data-serial="${h(onu.serial)}" data-pon="${h(onu.pon)}">Authorize ONU</button>`:''}</td></tr>`,'No unconfigured ONUs observed');await load();}catch(error){$('#discovery-results').innerHTML=notice('Discovery failed',h(error.message),true);}finally{button.disabled=false;}};}
function authorizeOnu(button){$('#editor-title').textContent='Authorize '+button.dataset.serial;$('#editor-description').textContent='Apply a service profile to the selected observed ONU. This sends a provisioning request to your OLT gateway.';$('#editor-fields').innerHTML=field('profileId','@profiles')+`<div class="field-note">Serial: ${h(button.dataset.serial)}<br>PON: ${h(button.dataset.pon)}</div>`;$('#editor-error').textContent='';$('#editor').showModal();$('#editor-form').onsubmit=async event=>{event.preventDefault();const submit=$('[type=submit]',event.currentTarget);submit.disabled=true;try{await api('records/devices/'+button.dataset.authorizeOlt+'/authorize','POST',{serial:button.dataset.serial,pon:button.dataset.pon,profileId:event.currentTarget.elements.profileId.value});$('#editor').close();await load();renderDiscovery();toast('ONU authorization verified by gateway');}catch(error){$('#editor-error').textContent=error.message;}finally{submit.disabled=false;}};}
