function schedule(delay=3000){clearTimeout(state.pollTimer);state.pollTimer=setTimeout(async()=>{if(!state.session?.user)return;if(document.hidden)return schedule();if(state.session.user.role==='installer'){try{state.rows.jobs=await api('records/jobs');$('#sync-status').textContent='Connected';}catch{}return schedule();}try{state.dashboard=await api('dashboard');state.rows.devices=state.dashboard.devices;state.rows.alerts=state.dashboard.alerts.concat(rows('alerts').filter(a=>a.status==='Resolved'));state.rows.jobs=state.dashboard.jobs;state.failures=0;$('#sync-status').textContent='Connected · updated '+new Date().toLocaleTimeString();if(state.page==='dashboard'&&!$('dialog[open]')&&!document.activeElement.closest('#dashboard-panels')){$('#dashboard-cards').innerHTML=dashboardCards();$('#dashboard-panels').innerHTML=dashboardPanels();}if($('#live-badge')){$('#live-badge').textContent='Connected';$('#live-badge').classList.remove('disconnected');}}catch{state.failures++;$('#sync-status').textContent='Reconnecting…';if($('#live-badge')){$('#live-badge').textContent='Reconnecting';$('#live-badge').classList.add('disconnected');}}schedule(state.failures?Math.min(12000,2000*2**state.failures):3000);},delay);}
function search(){const q=$('#search-query').value.toLowerCase().trim();$('#search-results').innerHTML=q?kinds.flatMap(k=>rows(k).filter(r=>Object.values(r).filter(v=>typeof v!=='object').join(' ').toLowerCase().includes(q)).map(r=>({kind:k,item:r}))).slice(0,25).map(({kind,item})=>`<button class="search-result" data-search-kind="${kind}" data-id="${item.id}">${h(item.name||item.title||item.reference)}<small>${h(names[kind])} · ${h(item.serial||item.customer||item.location||'')}</small></button>`).join('')||'<p class="list-empty">No matching records.</p>':'<p class="list-empty">Search across devices, jobs, customers, serials and network records.</p>';}
function exportCsv(kind){const items=filtered(kind,kind==='devices'?rows(kind).filter(d=>d.type===state.deviceType):rows(kind));const keys=Object.keys(forms[kind]);const csvCell=v=>'"'+String(v??'').replace(/^[=+\-@]/,"'$&").replace(/"/g,'""')+'"';const text=[keys,...items.map(r=>keys.map(k=>r[k]))].map(row=>row.map(csvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=kind+'-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function toggleTheme(){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('network-hub-theme',document.documentElement.dataset.theme);}catch{}if(state.session?.user)chrome();}
// Deleting a router: a router has customers, jobs, alerts, reports and a WireGuard peer linked to it, so a plain
// delete is refused. Forget it instead (preview, then type the name). Payments always stay; customers are kept but unassigned.
async function forgetRouter(id){const p=await api('routers/'+id+'/forget','POST',{customers:false}),x=p.summary,parts=[[x.customersOnIt,'customers (kept, unassigned)'],[x.routerJobs,'router jobs'],[x.alerts,'alerts'],[x.wireguardPeers,'WireGuard peer'],[x.radiusSessions,'sessions'],[x.settings,'stored reports'],[x.credentials,'credentials'],[x.hotspotLogs,'hotspot log lines'],[x.measurements,'graph points']].filter(([n])=>n).map(([n,l])=>n+' '+l);
 const typed=prompt(`Delete router ${p.router.name}?\n\nThis also removes: ${parts.join(', ')||'nothing else'}.\nPayments stay. Nothing is sent to the router.\nTo delete its customers too, use MikroTik → Link a MikroTik → Start over.\n\nType ${p.router.name} to delete it:`);
 if(typed===null)return;if(typed.trim()!==p.router.name){toast('Name did not match; nothing was deleted');return;}
 await api('routers/'+id+'/forget','POST',{apply:true,customers:false,confirm:typed.trim()});await load();render();toast(p.router.name+' deleted');}
document.addEventListener('click',async event=>{const target=event.target.closest('button,a,g[data-map-id]');if(!target)return;try{if(target.dataset.ticketOpen){openTicket(target.dataset.ticketOpen);return;}if(target.dataset.tview){try{localStorage.setItem('ticketView',target.dataset.tview);}catch{}for(const b of document.querySelectorAll('[data-tview]'))b.className='button '+(b.dataset.tview===target.dataset.tview?'primary':'secondary');paintList();return;}
 if(target.hasAttribute('data-close'))target.closest('dialog').close();
 if((target.dataset.add||target.dataset.editKind)&&['tickets','invoices','jobs'].includes(target.dataset.add||target.dataset.editKind)&&typeof radiusView!=='undefined'&&!radiusView.data){try{radiusView.data=await api('radius');}catch{}}if(target.dataset.add)openEditor(target.dataset.add,null,JSON.parse(target.dataset.defaults||'{}'));
 if(target.dataset.cpeJob)createCpeJob(target.dataset.cpeJob);
 if(target.dataset.teamTab){state.teamTab=target.dataset.teamTab;renderTeam();return;}if(target.dataset.roleEdit){editRole(target.dataset.roleEdit);return;}
 if(target.dataset.editKind){$('#detail-dialog').close();openEditor(target.dataset.editKind,target.dataset.id);}
 if(target.dataset.deleteKind==='devices'&&(state.rows.devices||[]).find(d=>d.id===target.dataset.id)?.type==='router'){await forgetRouter(target.dataset.id);return;}
 if(target.dataset.deleteKind){if(!confirm('Delete this '+names[target.dataset.deleteKind]+'?'))return;await api('records/'+target.dataset.deleteKind+'/'+target.dataset.id,'DELETE',{});await load();render();toast('Record deleted');}
 if(target.dataset.device)await monitor(target.dataset.device);
 if(target.dataset.connect)configureConnection(target.dataset.connect);
 if(target.dataset.poll){target.disabled=true;const result=await api('records/devices/'+target.dataset.poll+'/poll','POST',{});await load();await monitor(target.dataset.poll);toast(result.online?'Device check succeeded':result.error);target.disabled=false;}
 if(target.dataset.stockMove)openEditor('stockMoves',null,{stockId:target.dataset.stockMove});
 if(target.dataset.payment)openEditor('payments',null,{invoiceId:target.dataset.payment,amount:find('invoices',target.dataset.payment).amount-rows('payments').filter(p=>p.invoiceId===target.dataset.payment).reduce((n,p)=>n+p.amount,0)});
 if(target.hasAttribute('data-add-team'))editTeam();if(target.dataset.team)editTeam(target.dataset.team);
 if(target.dataset.cores)showCores(target.dataset.cores);if(target.dataset.odb)showOdb(target.dataset.odb);if(target.dataset.defaultPreset){await api('presets/default','POST',{id:state.defaultPresetId===target.dataset.defaultPreset?null:target.dataset.defaultPreset});await load();render();toast('Default preset saved');}
 if(target.dataset.assignOdb)assignOdb(target.dataset.assignOdb,target.dataset.port);
 if(target.dataset.clearOdbDevice){const onu=find('devices',target.dataset.clearOdbDevice);await api('records/devices/'+onu.id,'PATCH',{version:onu.version,odbId:'',odbPort:''});await load();showOdb(target.dataset.odb);toast('ONU unassigned');}
 if(target.hasAttribute('data-apply-preset'))presetApply();
 if(target.dataset.authorizeOlt)authorizeOnu(target);
 if(target.dataset.export)exportCsv(target.dataset.export);
 if(target.hasAttribute('data-refresh'))await refresh();
 if(target.hasAttribute('data-theme')||target.id==='theme-toggle')toggleTheme();
 if(target.dataset.mapId){if(target.dataset.mapKind==='devices')await monitor(target.dataset.mapId);else openEditor(target.dataset.mapKind,target.dataset.mapId);}
 if(target.dataset.searchKind){$('#search-dialog').close();if(target.dataset.searchKind==='devices')await monitor(target.dataset.id);else openEditor(target.dataset.searchKind,target.dataset.id);}
 if(target.id==='search-trigger'){$('#search-dialog').showModal();$('#search-query').focus();search();}
 if(target.id==='logout'){await api('logout','POST',{});state.session=null;showAuth(false);}
 if(target.id==='menu-toggle'){if(innerWidth<=760){document.body.classList.toggle('nav-open');$('#scrim').hidden=!document.body.classList.contains('nav-open');}else document.body.classList.toggle('collapsed');}
 if(target.id==='scrim'){document.body.classList.remove('nav-open');target.hidden=true;}
 if(target.id==='workspace-link')location.hash='settings';if(target.id==='profile-link')location.hash='me';
 if(target.id==='save-workspace'){await api('workspace','PATCH',{name:$('#workspace-name').value,description:$('#ws-description').value,address:$('#ws-address').value,email:$('#ws-email').value,phone:$('#ws-phone').value,country:$('#ws-country').value,currency:$('#ws-currency').value});await load();chrome();toast('ISP details saved');}
 }catch(error){toast(error.message);}finally{if(target.dataset.poll)target.disabled=false;}});
document.addEventListener('input',event=>{if(event.target.id==='list-query'){state.query=event.target.value;paintList();}if(event.target.id==='search-query')search();});
document.addEventListener('change',event=>{if(event.target.id==='list-status'){state.filter=event.target.value;paintList();}});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'&&state.session?.user){event.preventDefault();$('#search-dialog').showModal();$('#search-query').focus();search();}if(['Enter',' '].includes(event.key)&&event.target.dataset.mapId){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
window.addEventListener('hashchange',navigate);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.session?.user)schedule(100);});
setInterval(paintClock,1000);
async function init(){try{document.documentElement.dataset.theme=localStorage.getItem('network-hub-theme')||'light';}catch{}try{state.session=await api('session');if(state.session.user)await enter();else showAuth(state.session.setup);}catch(error){$('#auth-screen').innerHTML=`<section class="auth-card card"><h1>Server unavailable</h1><p>${h(error.message)}</p><p>Start the app with <code>npm start</code>, then reload this page.</p><button class="button primary" id="retry-start">Retry</button></section>`;$('#retry-start').onclick=init;}}
function configureSnmp(device){
 $('#detail-dialog').close();$('#editor-title').textContent='SNMP connection — '+device.name;$('#editor-description').textContent='Use SNMPv3 authentication and AES privacy when supported. SNMPv2c sends its community without encryption and should be confined to your private management network.';
 $('#editor-fields').innerHTML='<label>SNMP version<select name="version" id="snmp-version"><option value="3">SNMPv3 (authentication + AES privacy)</option><option value="2c">SNMPv2c (private network)</option></select></label><div id="snmp-v3-fields"><label>SNMP username<input name="username" autocomplete="off" required></label><label>Authentication<select name="authProtocol"><option value="sha256">SHA-256</option><option value="sha">SHA-1 (device compatibility)</option></select></label><label>Authentication passphrase<input name="authKey" type="password" required minlength="8" autocomplete="off"></label><label>Privacy passphrase<input name="privKey" type="password" required minlength="8" autocomplete="off"></label></div><div id="snmp-v2-fields" hidden><label>Read-only community<input name="community" type="password" autocomplete="off" disabled></label></div>';
 $('#snmp-version').onchange=event=>{const v3=event.target.value==='3';$('#snmp-v3-fields').hidden=!v3;$('#snmp-v2-fields').hidden=v3;$$('input,select',$('#snmp-v3-fields')).forEach(el=>{el.disabled=!v3;if(el.tagName==='INPUT')el.required=v3;});const community=$('[name=community]',$('#editor-form'));community.disabled=v3;community.required=!v3;};
 $('#editor-error').textContent='';$('#editor').showModal();$('#editor-form').onsubmit=async event=>{event.preventDefault();const button=$('[type=submit]',event.currentTarget);button.disabled=true;try{await api('records/devices/'+device.id+'/connection','POST',Object.fromEntries(new FormData(event.currentTarget)));$('#editor-form').reset();await load();$('#editor').close();await monitor(device.id);toast('SNMP credentials saved');}catch(error){$('#editor-error').textContent=error.message;}finally{button.disabled=false;}};
}
window.addEventListener('DOMContentLoaded',()=>{const m=location.hash.match(/^#invite=([A-Za-z0-9_-]{30,80})$/);if(m)return inviteScreen(m[1]);init();});

